"""Legacy deterministic courses used only by backend tests."""

from __future__ import annotations


def _question(
    question_id: str,
    prompt: str,
    answer: str,
    *,
    skill: str,
    hint: str,
    explanation: str,
    verification_expression: str,
) -> dict:
    return {
        "id": question_id,
        "type": "numeric",
        "prompt": prompt,
        "answer": answer,
        "skill": skill,
        "hint": hint,
        "explanation": explanation,
        "verificationExpression": verification_expression,
    }


def _course(
    grade: int,
    node_code: str,
    title: str,
    objective: str,
    intro: str,
    questions: list[dict],
) -> dict:
    return {
        "id": f"primary_math_g{grade}_{node_code}_v1",
        "version": "1.0.0",
        "gradeCode": f"primary_{grade}",
        "subject": "math",
        "nodeCode": node_code,
        "title": title,
        "objective": objective,
        "status": "published",
        "content": {
            "intro": intro,
            "estimatedMinutes": 10,
            "questions": questions,
        },
    }


